pipeline {
    agent none
    stages {
        stage('Build') {
            agent { label 'linux-large' }
            steps {
                sh 'make build'
            }
        }
        stage('Test') {
            agent { label 'linux-small' }
            steps {
                sh './run-tests'
            }
        }
    }
}

pipeline {
    agent { label 'heavy-worker' }
    stages {
        stage('Deploy') {
            steps {
                sh './prepare-deploy.sh'
                input message: 'Approve deployment?'
                sh './deploy.sh'
            }
        }
    }
}
